+        public async Task<List<HumanResourceApprovalResp>> GetApprovalList(HumanResourceApprovalReq req)
+        {
+            if (req.Origins.Any() && !req.Origins.Contains(ApprovalOrigin.MisconductReport))
+            {
+                return new List<HumanResourceApprovalResp>();
+            }
+
+            var loginUser = _auth.GetCurrentUser()?.User ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var scope = await GetApprovalPermissionScope(loginUser.Id);
+            var reports = await QueryReports(req.Name, ConvertDocStatus(req.DocStatus));
+
+            reports = req.Status switch
+            {
+                ApprovalFilterStatus.未决 => reports.Where(x => ContainsUserId(x.CurrentApproverId, loginUser.Id)).ToList(),
+                ApprovalFilterStatus.我创建的 => reports.Where(x => x.Creator == loginUser.Id).ToList(),
+                ApprovalFilterStatus.已批准 => reports.Where(x => ContainsUserId(x.ApprovedUserId, loginUser.Id)).ToList(),
