+        /// <summary>
+        /// 按关键字和单据状态查询过失行为报告原始数据集合。
+        /// </summary>
+        /// <param name="keyword">列表关键字，可匹配编号、人员、部门、事实描述及处罚信息。</param>
+        /// <param name="docStatus">需要筛选的单据状态；为空时不过滤状态。</param>
+        /// <returns>符合条件的过失行为报告集合异步任务。</returns>
+        private async Task<List<MisconductReport>> QueryReports(string keyword, MisconductReportStatusEnum? docStatus)
+        {
+            keyword = keyword?.Trim();
+            var reports = await UnitWork.Find<MisconductReport>(null)
+                .WhereIf(docStatus.HasValue, x => x.Status == docStatus.Value)
+                .OrderByDescending(x => x.UpdateDate)
+                .ToListAsync();
+
+            if (string.IsNullOrWhiteSpace(keyword))
+            {
+                return reports;
+            }
+
+            return reports.Where(x =>
+                    x.ApprovalNumber.ToString().Contains(keyword, StringComparison.OrdinalIgnoreCase)
+                    || ContainsText(x.ReporterName, keyword)
+                    || ContainsText(x.PartyName, keyword)
+                    || ContainsText(x.PartyDepartmentCode, keyword)
+                    || ContainsText(x.PartyPosition, keyword)
+                    || ContainsText(x.FactDescription, keyword)
+                    || ContainsText(x.HandlingOpinion, keyword)
+                    || ContainsText(x.BehaviorCategoryPathNames, keyword)
+                    || ContainsText(x.PunishmentCategoryName, keyword))
+                .ToList();
