+        /// <summary>
+        /// 按审批中心权限规则过滤聚合审批列表中可见的过失行为报告。
+        /// </summary>
+        /// <param name="reports">待过滤的单据集合。</param>
+        /// <param name="scope">当前用户在过失行为模块中的审批查看范围。</param>
+        /// <param name="loginUserId">当前用户标识。</param>
+        /// <returns>权限过滤后的过失行为报告集合异步任务。</returns>
+        private async Task<List<MisconductReport>> ApplyApprovalPermissions(
+            List<MisconductReport> reports,
+            MisconductPermissionScope scope,
+            string loginUserId)
+        {
+            if (scope.CanViewAll || !reports.Any())
+            {
+                return reports;
+            }
+            if (scope.CanViewDepartment)
+            {
+                var departmentUserIds = await GetCurrentDepartmentUserIds(loginUserId);
+                return reports.Where(x =>
+                        departmentUserIds.Contains(x.Creator)
+                        || departmentUserIds.Contains(x.ReporterUserId)
+                        || departmentUserIds.Contains(x.PartyUserId)
+                        || ContainsUserId(x.CurrentApproverId, loginUserId)
+                        || ContainsUserId(x.ApprovedUserId, loginUserId)
+                        || ContainsUserId(x.RejectedUserId, loginUserId))
+                    .ToList();
+            }
+            if (scope.CanViewSelf || !scope.HasModulePermission)
+            {
+                return reports.Where(x =>
+                        x.Creator == loginUserId
+                        || x.ReporterUserId == loginUserId
+                        || x.PartyUserId == loginUserId
+                        || ContainsUserId(x.CurrentApproverId, loginUserId)
+                        || ContainsUserId(x.ApprovedUserId, loginUserId)
+                        || ContainsUserId(x.RejectedUserId, loginUserId))
+                    .ToList();
+            }
+
+            return new List<MisconductReport>();
+        }
+
+        /// <summary>
+        /// 规范化处罚措施集合；优先使用子表明细，若子表为空则回退到主表中的兼容字段。
+        /// </summary>
+        /// <param name="punishments">处罚措施明细集合。</param>
+        /// <param name="report">过失行为报告主表数据。</param>
+        /// <returns>按排序号整理后的处罚措施集合。</returns>
+        private static List<MisconductReportPunishment> NormalizePunishments(
+            IEnumerable<MisconductReportPunishment> punishments,
+            MisconductReport report)
+        {
+            var result = punishments?
+                .Where(x => x != null && !string.IsNullOrWhiteSpace(x.PunishmentCategoryId))
+                .OrderBy(x => x.SortNo)
+                .ThenBy(x => x.Id)
+                .ToList() ?? new List<MisconductReportPunishment>();
+            if (result.Any())
+            {
+                return result;
+            }
+            if (string.IsNullOrWhiteSpace(report.PunishmentCategoryId)
+                && string.IsNullOrWhiteSpace(report.PunishmentCategoryName)
+                && string.IsNullOrWhiteSpace(report.PunishmentExtraValue))
+            {
+                return result;
+            }
+
+            result.Add(new MisconductReportPunishment
+            {
+                ReportId = report.Id,
+                PunishmentCategoryId = report.PunishmentCategoryId,
+                PunishmentCategoryCode = report.PunishmentCategoryCode,
+                PunishmentCategoryName = report.PunishmentCategoryName,
+                PunishmentExtraValue = report.PunishmentExtraValue,
+                PunishmentExtraUnit = report.PunishmentExtraUnit,
+                SortNo = 1,
+            });
+            return result;
+        }
