+        /// <summary>
+        /// 判断当前用户是否可以查看指定的过失行为报告详情。
+        /// </summary>
+        /// <param name="report">待校验访问权限的过失行为报告。</param>
+        /// <param name="loginUserId">当前登录用户标识。</param>
+        /// <returns>若当前用户可访问该单据则返回 <see langword="true"/>；否则返回 <see langword="false"/>。</returns>
+        private async Task<bool> CanAccessReport(MisconductReport report, string loginUserId)
+        {
+            if (HasDirectAccessRelation(report, loginUserId))
+            {
+                return true;
+            }
+
+            var scope = await GetPermissionScope(loginUserId);
+            if (scope.CanViewAll || scope.PermissionDepartments.Contains(report.PartyDepartmentCode))
+            {
+                return true;
+            }
+            if (scope.CanViewSelf && report.PartyUserId == loginUserId)
+            {
+                return true;
+            }
+            if (scope.CanViewDepartment)
+            {
+                var ownDepartments = await GetUserDepartmentNames(loginUserId);
+                return ownDepartments.Contains(report.PartyDepartmentCode);
+            }
+
+            return false;
+        }
