+        /// <summary>
+        /// 解析当前用户在过失行为审批聚合列表中的查看权限范围。
+        /// </summary>
+        /// <param name="userId">待解析权限的用户标识。</param>
+        /// <returns>包含模块权限和查看范围的权限对象异步任务。</returns>
+        private async Task<MisconductPermissionScope> GetApprovalPermissionScope(string userId)
+        {
+            if (userId == Define.ADMINID)
+            {
+                return new MisconductPermissionScope
+                {
+                    CanViewAll = true,
+                    HasModulePermission = true,
+                };
+            }
+            var scope = new MisconductPermissionScope();
+            var roles = _revelanceManagerApp.Get(Define.USERROLE, true, userId);
+            var moduleElements = await GetModuleElementsByCode(roles, MisconductModuleCode);
+            if (!moduleElements.Any())
+            {
+                return scope;
+            }
+            
+            scope.CanViewAll = moduleElements.Exists(x => x.DomId == ViewAll);
+            scope.CanViewDepartment = moduleElements.Exists(x => x.DomId == ViewDept);
+            scope.CanViewSelf = moduleElements.Exists(x => x.DomId == ViewSelf);
+            scope.HasModulePermission = scope.CanViewAll || scope.CanViewDepartment || scope.CanViewSelf;
+            scope.IsSelfOnly = !scope.CanViewAll && !scope.CanViewDepartment && scope.CanViewSelf;
+            return scope;
+        }
+
+        /// <summary>
+        /// 判断用户是否与单据存在直接关联关系，例如发起人、报告人、当事人或审批参与人。
+        /// </summary>
+        /// <param name="report">待判断的过失行为报告。</param>
+        /// <param name="userId">当前用户标识。</param>
+        /// <returns>若存在直接关联关系则返回 <see langword="true"/>；否则返回 <see langword="false"/>。</returns>
+        private static bool HasDirectAccessRelation(MisconductReport report, string userId)
+        {
+            return report.Creator == userId
+                || report.ReporterUserId == userId
+                || report.PartyUserId == userId
+                || ContainsUserId(report.CurrentApproverId, userId)
+                || ContainsUserId(report.ApprovedUserId, userId)
+                || ContainsUserId(report.RejectedUserId, userId);
+        }
+
+        /// <summary>
+        /// 解析当前用户在过失行为报告模块中的数据查看范围，并合并人资基础数据授权部门。
+        /// </summary>
+        /// <param name="userId">待解析权限的用户标识。</param>
+        /// <returns>包含模块权限和授权部门范围的权限对象异步任务。</returns>
+        private async Task<MisconductPermissionScope> GetPermissionScope(string userId)
+        {
+            var scope = new MisconductPermissionScope();
+            var roles = _revelanceManagerApp.Get(Define.USERROLE, true, userId);
+            // 按模块
+            var moduleElements = await GetModuleElementsByCode(roles, MisconductModuleCode);
+            if (moduleElements.Any())
+            {
+                scope.CanViewAll = moduleElements.Exists(x => x.DomId == ViewAll);
+                scope.CanViewDepartment = moduleElements.Exists(x => x.DomId == ViewDept);
+                scope.CanViewSelf = moduleElements.Exists(x => x.DomId == ViewSelf);
+            }
+            else
+            {
+                // 人资模块兜底
+                moduleElements = await GetModuleElementsByCode(roles, HumanResourceModuleCode);
+                if (moduleElements.Any())
+                {
+                    scope.CanViewAll = moduleElements.Exists(x => x.DomId == HrViewAll);
+                    scope.CanViewDepartment = moduleElements.Exists(x => x.DomId == HrViewDepartment);
+                    scope.CanViewSelf = !scope.CanViewAll && !scope.CanViewDepartment;
+                }
+            }
+
+            // 权限配置
+            var permissionDetails = await UnitWork.Find<HumanResourcePermissionDetail>(x => x.UserId == userId).ToListAsync();
+            var permissionIds = permissionDetails.Select(x => x.PermissionId).Distinct().ToList();
+            if (permissionIds.Any())
+            {
+                var permissions = await UnitWork.Find<HumanResourcePermission>(x =>
+                        permissionIds.Contains(x.Id) && x.DataType == HumanResourceDataTypeEnums.BaseData)
+                    .ToListAsync();
+                var deptIds = permissions
+                    .Where(x => !string.IsNullOrWhiteSpace(x.DeptIds))
+                    .SelectMany(x => SplitValues(x.DeptIds))
+                    .Distinct()
+                    .ToList();
+                if (deptIds.Any())
+                {
+                    scope.PermissionDepartments = await UnitWork.Find<Repository.Domain.Org>(x => deptIds.Contains(x.Id))
+                        .Select(x => x.Name)
+                        .Distinct()
+                        .ToListAsync();
+                }
+            }
+
+            scope.IsSelfOnly = !scope.CanViewAll && !scope.CanViewDepartment && !scope.PermissionDepartments.Any() && scope.CanViewSelf;
+            return scope;
+        }
