+        /// <summary>
+        /// 获取当前用户所在部门的全部在岗用户标识集合，用于部门级审批可见性过滤。
+        /// </summary>
+        /// <param name="userId">当前用户标识。</param>
+        /// <returns>包含当前用户及其同部门成员标识的异步任务。</returns>
+        private async Task<HashSet<string>> GetCurrentDepartmentUserIds(string userId)
+        {
+            var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
+            if (!string.IsNullOrWhiteSpace(userId))
+            {
+                result.Add(userId);
+            }
+
+            var departmentIds = await UnitWork.Find<Relevance>(x => x.FirstId == userId && x.Key == Define.USERORG)
+                .Select(x => x.SecondId)
+                .Distinct()
+                .ToListAsync();
+            if (!departmentIds.Any())
+            {
+                return result;
+            }
+
+            var departmentUserIds = await UnitWork.Find<Relevance>(x => departmentIds.Contains(x.SecondId) && x.Key == Define.USERORG)
+                .Select(x => x.FirstId)
+                .Distinct()
+                .ToListAsync();
+            foreach (var item in departmentUserIds.Where(x => !string.IsNullOrWhiteSpace(x)))
+            {
+                result.Add(item);
+            }
+
+            return result;
