+        /// <summary>
+        /// 根据角色集合和模块编码查询已授权的模块元素列表。
+        /// </summary>
+        /// <param name="roleIds">待查询的角色标识集合。</param>
+        /// <param name="moduleCode">模块编码。</param>
+        /// <returns>角色在指定模块下拥有的模块元素集合异步任务。</returns>
+        private async Task<List<ModuleElement>> GetModuleElementsByCode(List<string> roleIds, string moduleCode)
+        {
+            if (roleIds == null || roleIds.Count == 0)
+            {
+                return new List<ModuleElement>();
+            }
+
+            var modules = from m in UnitWork.Find<Module>(null)
+                          join r in UnitWork.Find<Relevance>(null) on m.Id equals r.SecondId
+                          join role in UnitWork.Find<Role>(null) on r.FirstId equals role.Id
+                          where r.Key == Define.ROLEMODULE && roleIds.Contains(r.FirstId) && m.Code == moduleCode
+                          select new { ModuleId = m.Id, RoleId = role.Id };
+
