+        /// <summary>
+        /// 校验过失分类路径是否合法，并生成落库和流程表单所需的完整分类路径信息。
+        /// </summary>
+        /// <param name="behaviorCategoryIds">按层级顺序提交的过失分类路径标识集合。</param>
+        /// <returns>包含路径编号、编码、名称和最终叶子节点信息的异步任务。</returns>
+        /// <exception cref="ArgumentException">分类路径为空、重复、父子关系不匹配或配置不可用时抛出。</exception>
+        private async Task<BehaviorCategorySelection> ResolveBehaviorCategorySelection(List<string> behaviorCategoryIds)
+        {
+            var normalizedIds = behaviorCategoryIds?
+                .Select(x => x?.Trim())
+                .Where(x => !string.IsNullOrWhiteSpace(x))
+                .ToList() ?? new List<string>();
+            if (!normalizedIds.Any())
+            {
+                throw new ArgumentException("过失类型不能为空");
+            }
+            if (normalizedIds.Count != normalizedIds.Distinct(StringComparer.OrdinalIgnoreCase).Count())
+            {
+                throw new ArgumentException("过失类型路径存在重复节点");
+            }
+
+            var categories = await UnitWork.Find<Category>(x => normalizedIds.Contains(x.Id) && x.TypeId == BehaviorCategoryTypeId && x.Enable)
+                .ToListAsync();
+            if (categories.Count != normalizedIds.Count)
+            {
+                throw new ArgumentException("过失类型配置不存在或已禁用");
+            }
+
+            var categoryDict = categories.ToDictionary(x => x.Id, x => x);
+            var orderedCategories = new List<Category>();
+
+            for (var i = 0; i < normalizedIds.Count; i++)
+            {
+                if (!categoryDict.TryGetValue(normalizedIds[i], out var category))
+                {
+                    throw new ArgumentException("过失类型配置不存在或已禁用");
+                }
+
+                var parentId = category.Extension?.Trim();
+                if (i == 0)
+                {
+                    if (!string.IsNullOrWhiteSpace(parentId))
+                    {
+                        throw new ArgumentException("过失类型路径必须从根节点开始");
+                    }
+                }
+                else if (!string.Equals(parentId, orderedCategories[i - 1].Id, StringComparison.OrdinalIgnoreCase))
+                {
+                    throw new ArgumentException("过失类型路径父子关系不匹配");
+                }
+
+                orderedCategories.Add(category);
+            }
+
+            var selectedCategory = orderedCategories[orderedCategories.Count - 1];
+            return new BehaviorCategorySelection
+            {
+                CategoryIds = orderedCategories.Select(x => x.Id).ToList(),
+                PathIds = string.Join(",", orderedCategories.Select(x => x.Id)),
+                PathCodes = string.Join(",", orderedCategories.Select(x => x.DtCode)),
+                PathNames = string.Join("/", orderedCategories.Select(x => x.Name)),
+                Level = orderedCategories.Count,
+                FinalCategoryId = selectedCategory.Id,
+                FinalCategoryCode = selectedCategory.DtCode,
+                FinalCategoryName = selectedCategory.Name,
+            };
+        }
