+        /// <summary>
+        /// 根据 HR 审批请求构建定级结果和处罚措施明细，并校验等级、处罚和有效期约束。
+        /// </summary>
+        /// <param name="req">HR 节点提交的审批请求。</param>
+        /// <returns>HR 定级结果；若当前审批不是同意则返回 <see langword="null"/>。</returns>
+        /// <exception cref="ArgumentException">等级、处罚措施、附加值或处罚有效期配置不合法时抛出。</exception>
+        private HrDecisionData BuildHrDecision(MisconductReportApprovalReq req)
+        {
+            if (req.Result != ApprovalType.Agree)
+            {
+                return null;
+            }
+
+            if (string.IsNullOrWhiteSpace(req.SeverityCategoryId))
+            {
+                throw new ArgumentException("HR定级时，过失等级不能为空");
+            }
+            var punishmentInputs = (req.Punishments ?? new List<MisconductPunishmentReq>())
+                .Where(x => x != null && !string.IsNullOrWhiteSpace(x.PunishmentCategoryId))
+                .Select((x, index) => new
+                {
+                    PunishmentCategoryId = x.PunishmentCategoryId.Trim(),
+                    PunishmentExtraValue = x.PunishmentExtraValue?.Trim(),
+                    SortNo = index + 1,
+                })
+                .ToList();
+            if (!punishmentInputs.Any())
+            {
+                throw new ArgumentException("HR定级时，处罚措施不能为空");
+            }
+            var duplicatedPunishment = punishmentInputs
+                .GroupBy(x => x.PunishmentCategoryId, StringComparer.OrdinalIgnoreCase)
+                .FirstOrDefault(x => x.Count() > 1);
+            if (duplicatedPunishment != null)
+            {
+                throw new ArgumentException("HR定级时，处罚措施不能重复选择");
+            }
+
+            var severityCategory = UnitWork.Find<Category>(x =>
+                    x.Id == req.SeverityCategoryId && x.TypeId == SeverityCategoryTypeId && x.Enable)
+                .FirstOrDefault()
+                ?? throw new ArgumentException("过失等级配置不存在或已禁用");
+            var punishmentCategoryIds = punishmentInputs.Select(x => x.PunishmentCategoryId).Distinct().ToList();
+            var punishmentCategories = UnitWork.Find<Category>(x =>
+                    punishmentCategoryIds.Contains(x.Id) && x.TypeId == PunishmentCategoryTypeId && x.Enable)
+                .ToList();
+            if (punishmentCategories.Count != punishmentCategoryIds.Count)
+            {
+                throw new ArgumentException("处罚措施配置不存在或已禁用");
+            }
+            var punishmentCategoryDict = punishmentCategories
+                .GroupBy(x => x.Id)
+                .ToDictionary(x => x.Key, x => x.First());
+            if (req.PunishmentValidStartDate.HasValue ^ req.PunishmentValidEndDate.HasValue)
+            {
+                throw new ArgumentException("处罚有效期开始和结束日期需同时填写");
+            }
+            if (req.PunishmentValidStartDate > req.PunishmentValidEndDate)
+            {
+                throw new ArgumentException("处罚有效期开始日期不能大于结束日期");
+            }
+
+            var punishments = new List<HrDecisionPunishmentData>();
+            foreach (var item in punishmentInputs)
+            {
+                if (!punishmentCategoryDict.TryGetValue(item.PunishmentCategoryId, out var punishmentCategory))
+                {
+                    throw new ArgumentException("处罚措施配置不存在或已禁用");
+                }
+
+                var punishmentConfig = GetPunishmentConfig(punishmentCategory.Extension);
+                if (punishmentConfig.NeedInput && string.IsNullOrWhiteSpace(item.PunishmentExtraValue))
+                {
+                    throw new ArgumentException($"处罚措施“{punishmentCategory.Name}”需要填写附加值");
+                }
+
+                punishments.Add(new HrDecisionPunishmentData
+                {
+                    PunishmentCategoryId = punishmentCategory.Id,
+                    PunishmentCategoryCode = punishmentCategory.DtCode,
+                    PunishmentCategoryName = punishmentCategory.Name,
+                    PunishmentExtraValue = item.PunishmentExtraValue,
+                    PunishmentExtraUnit = punishmentConfig.InputUnit,
+                    SortNo = item.SortNo,
+                });
+            }
+
+            return new HrDecisionData
+            {
+                SeverityCategoryId = severityCategory.Id,
+                SeverityCategoryCode = severityCategory.DtCode,
+                SeverityCategoryName = severityCategory.Name,
+                Punishments = punishments,
+                PunishmentValidStartDate = req.PunishmentValidStartDate?.Date,
+                PunishmentValidEndDate = req.PunishmentValidEndDate?.Date,
+            };
+        }
