+        /// </summary>
+        /// <param name="extension">分类扩展字段的 JSON 文本。</param>
+        /// <returns>解析得到的处罚配置对象；无法解析时返回默认空配置。</returns>
+        private static PunishmentConfig GetPunishmentConfig(string extension)
+        {
+            if (string.IsNullOrWhiteSpace(extension))
+            {
+                return new PunishmentConfig();
+            }
+
+            try
+            {
+                var token = JToken.Parse(extension);
+                var needInput = GetBooleanValue(token, "NeedInput")
+                    || GetBooleanValue(token, "needInput")
+                    || GetBooleanValue(token, "IsNeedInput")
+                    || GetBooleanValue(token, "isNeedInput")
+                    || GetBooleanValue(token, "RequireInput")
+                    || GetBooleanValue(token, "requireInput");
+
+                var unit = GetStringValue(token, "InputUnit")
+                    ?? GetStringValue(token, "inputUnit")
+                    ?? GetStringValue(token, "Unit")
+                    ?? GetStringValue(token, "unit");
+
+                return new PunishmentConfig
+                {
+                    NeedInput = needInput,
+                    InputUnit = unit,
+                };
+            }
+            catch
+            {
+                return new PunishmentConfig();
+            }
+        }
