+                                      join r in UnitWork.Find<Relevance>(x => x.Key == Define.USERORG) on u.Id equals r.FirstId into urs
+                                      from r in urs.DefaultIfEmpty()
+                                      join o in UnitWork.Find<Repository.Domain.Org>(null) on r.SecondId equals o.Id into ros
+                                      from o in ros.DefaultIfEmpty()
+                                      select new
+                                      {
+                                          u.Id,
+                                          UserName = u.Name,
+                                          OrgName = o.Name,
+                                      }).ToListAsync();
+
+            return creatorInfos.GroupBy(x => x.Id).ToDictionary(x => x.Key, x =>
+            {
+                var info = x.First();
+                if (info.Id == Define.ADMINID || info.UserName == Define.SUPERADMIN || string.IsNullOrWhiteSpace(info.OrgName))
+                {
+                    return info.UserName;
+                }
+                return $"{info.OrgName}-{info.UserName}";
+            });
+        }
