+        /// <summary>
+        /// 将审批中心的通用单据状态枚举转换为过失行为报告状态枚举。
+        /// </summary>
+        /// <param name="status">审批中心的单据状态枚举。</param>
+        /// <returns>对应的过失行为报告状态；无法映射时返回 <see langword="null"/>。</returns>
+        private static MisconductReportStatusEnum? ConvertDocStatus(ApprovalDocStatus? status)
+        {
+            return status switch
+            {
+                ApprovalDocStatus.草稿 => MisconductReportStatusEnum.Recall,
+                ApprovalDocStatus.审批中 => MisconductReportStatusEnum.Audit,
+                ApprovalDocStatus.已批准 => MisconductReportStatusEnum.Pass,
