+        /// <summary>
+        /// 判断源字符串是否包含指定关键字，忽略大小写。
+        /// </summary>
+        /// <param name="source">源字符串。</param>
+        /// <param name="keyword">待匹配关键字。</param>
+        /// <returns>若包含关键字则返回 <see langword="true"/>；否则返回 <see langword="false"/>。</returns>
+        private static bool ContainsText(string source, string keyword)
+        {
+            return !string.IsNullOrWhiteSpace(source)
+                && source.Contains(keyword, StringComparison.OrdinalIgnoreCase);
+        }
+
+        /// <summary>
+        /// 按逗号拆分字符串并移除空白项。
+        /// </summary>
+        /// <param name="value">待拆分的字符串。</param>
+        /// <returns>拆分后的字符串数组。</returns>
+        private static string[] SplitValues(string value)
+        {
+            if (string.IsNullOrWhiteSpace(value))
+            {
+                return Array.Empty<string>();
+            }
+
+            return value.Split(',', StringSplitOptions.RemoveEmptyEntries)
+                .Select(x => x.Trim())
+                .Where(x => !string.IsNullOrWhiteSpace(x))
+                .ToArray();
+        }
